css:
:root {
  --paper: #f3f0e6;
  --paper-high: #fbf9f2;
  --paper-deep: #ebe7d9;
  --ink: #10261b;
  --ink-soft: #46574c;
  --muted: #626f66;
  --line: rgba(16, 38, 27, 0.14);
  --line-strong: rgba(16, 38, 27, 0.28);
  --lime: #d9f36b;
  --lime-deep: #badd43;
  --lime-wash: #eaf3c9;
  --amber: #e9a45f;
  --amber-wash: #f6e7d2;
  --sage: #dce5d2;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --mono: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
  --gutter: clamp(20px, 4.45vw, 64px);
  --shell: 1408px;
  --radius: 26px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
  scroll-padding-top: 96px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: clip;
}

body::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 100;
  pointer-events: none;
  opacity: 0.03;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}

::selection {
  background: var(--lime);
  color: var(--ink);
}

a {
  color: inherit;
}

p,
h1,
h2,
h3 {
  margin-top: 0;
}

svg {
  display: block;
}

.shell {
  width: 100%;
  max-width: var(--shell);
  margin-inline: auto;
  padding-inline: var(--gutter);
}

.skip-link {
  position: fixed;
  top: 12px;
  left: 12px;
  z-index: 200;
  padding: 10px 16px;
  border-radius: 999px;
  background: var(--ink);
  color: var(--paper);
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transform: translateY(-160%);
  transition: transform 160ms ease;
}

.skip-link:focus {
  transform: translateY(0);
  outline: 2px solid var(--lime);
  outline-offset: 3px;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.14em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow-dot {
  position: relative;
  display: inline-block;
  flex: 0 0 auto;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ink);
  box-shadow: 0 0 0 4px rgba(186, 221, 67, 0.66);
}

.eyebrow--light {
  color: rgba(243, 240, 230, 0.66);
}

.eyebrow--light .eyebrow-dot {
  background: var(--lime);
  box-shadow: 0 0 0 4px rgba(217, 243, 107, 0.12);
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  border-bottom: 1px solid var(--line);
  background: rgba(243, 240, 230, 0.86);
  -webkit-backdrop-filter: blur(16px) saturate(1.15);
  backdrop-filter: blur(16px) saturate(1.15);
}

.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  min-height: 82px;
  gap: 24px;
}

.brand {
  display: inline-flex;
  align-items: center;
  justify-self: start;
  gap: 10px;
  color: var(--ink);
  font-size: 20px;
  font-weight: 680;
  letter-spacing: -0.035em;
  line-height: 1;
  text-decoration: none;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  flex: 0 0 auto;
}

.brand-mark svg {
  width: 100%;
  height: 100%;
}

.brand:focus-visible,
.primary-nav a:focus-visible,
.header-cta:focus-visible,
.button:focus-visible,
.text-link:focus-visible,
.cta-foot a:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 4px;
  border-radius: 4px;
}

.primary-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(24px, 3vw, 40px);
}

.primary-nav a {
  position: relative;
  padding: 7px 0;
  color: var(--ink-soft);
  font-size: 13px;
  font-weight: 560;
  text-decoration: none;
  transition: color 160ms ease;
}

.primary-nav a::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 2px;
  left: 0;
  height: 1px;
  background: var(--ink);
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 220ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

.primary-nav a:hover {
  color: var(--ink);
}

.primary-nav a:hover::after {
  transform: scaleX(1);
  transform-origin: left;
}

.header-cta {
  display: inline-flex;
  align-items: center;
  justify-self: end;
  gap: 11px;
  min-height: 40px;
  padding: 0 16px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  color: var(--ink);
  font-size: 12.5px;
  font-weight: 650;
  letter-spacing: -0.01em;
  text-decoration: none;
  transition: color 180ms ease, background 180ms ease, border-color 180ms ease;
}

.header-cta svg {
  width: 13px;
  height: 13px;
  transition: transform 180ms ease;
}

.header-cta:hover {
  border-color: var(--ink);
  background: var(--ink);
  color: var(--paper);
}

.header-cta:hover svg {
  transform: translate(2px, -2px);
}

.hero {
  position: relative;
  isolation: isolate;
  overflow: hidden;
}

.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(ellipse 48% 52% at 83% 49%, rgba(217, 243, 107, 0.24), transparent 72%),
    linear-gradient(90deg, rgba(16, 38, 27, 0.042) 1px, transparent 1px);
  background-size: auto, 98px 100%;
  -webkit-mask-image: linear-gradient(to bottom, transparent 0, #000 12%, #000 86%, transparent 100%);
  mask-image: linear-gradient(to bottom, transparent 0, #000 12%, #000 86%, transparent 100%);
}

.hero-inner {
  display: grid;
  grid-template-columns: minmax(0, 1.04fr) minmax(0, 0.96fr);
  align-items: center;
  gap: clamp(32px, 5vw, 84px);
  padding-top: clamp(58px, 6.2vw, 94px);
  padding-bottom: clamp(68px, 7vw, 108px);
}

.hero-copy {
  position: relative;
  z-index: 2;
  max-width: 672px;
}

.hero-title {
  max-width: 660px;
  margin: 26px 0 27px;
  color: var(--ink);
  font-family: var(--serif);
  font-size: clamp(3.55rem, 7.05vw, 6.8rem);
  font-weight: 400;
  letter-spacing: -0.058em;
  line-height: 0.885;
}

.hero-line {
  display: block;
}

.hero-title em {
  position: relative;
  display: inline-block;
  font-style: italic;
  font-weight: 400;
  letter-spacing: -0.045em;
}

.hero-underline {
  position: absolute;
  right: -0.01em;
  bottom: -0.035em;
  left: 0.015em;
  width: calc(100% - 0.005em);
  height: 0.18em;
  overflow: visible;
  color: var(--lime-deep);
  pointer-events: none;
}

.hero-underline path {
  fill: none;
  stroke: currentColor;
  stroke-width: 6;
  stroke-linecap: round;
  vector-effect: non-scaling-stroke;
}

.hero-lede {
  max-width: 57ch;
  margin: 0 0 32px;
  color: var(--ink-soft);
  font-size: clamp(1.05rem, 1.38vw, 1.25rem);
  font-weight: 400;
  letter-spacing: -0.012em;
  line-height: 1.55;
  text-wrap: pretty;
}

.hero-lede strong {
  color: var(--ink);
  font-weight: 560;
}

.hero-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px 24px;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-height: 56px;
  padding: 6px 7px 6px 23px;
  border: 1px solid var(--ink);
  border-radius: 999px;
  background: var(--ink);
  color: var(--paper);
  font-size: 14.5px;
  font-weight: 620;
  letter-spacing: -0.01em;
  text-decoration: none;
  transition: background 220ms ease, transform 220ms ease, box-shadow 220ms ease;
}

.button-icon {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: var(--lime);
  color: var(--ink);
  transition: transform 220ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

.button-icon svg {
  width: 16px;
  height: 16px;
}

.button:hover {
  background: #1a3a29;
  box-shadow: 0 9px 26px rgba(16, 38, 27, 0.16);
  transform: translateY(-2px);
}

.button:hover .button-icon {
  transform: translateX(3px);
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 6px 2px;
  border-bottom: 1px solid var(--line-strong);
  color: var(--ink);
  font-size: 14.5px;
  font-weight: 620;
  letter-spacing: -0.01em;
  text-decoration: none;
  transition: border-color 180ms ease;
}

.text-link svg {
  width: 14px;
  height: 14px;
  transition: transform 180ms ease;
}

.text-link:hover {
  border-color: var(--ink);
}

.text-link:hover svg {
  transform: translateX(3px);
}

.hero-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 30px 0 0;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.035em;
  line-height: 1.5;
}

.hero-meta::before {
  content: "";
  width: 24px;
  height: 1px;
  flex: 0 0 auto;
  background: var(--line-strong);
}

.hero-art {
  position: relative;
  width: 100%;
  max-width: 586px;
  justify-self: end;
  padding: 10px 16px 48px 0;
}

.art-backdrop {
  position: absolute;
  top: 24px;
  right: 0;
  bottom: 28px;
  left: 22px;
  border-radius: 30px;
  background: var(--lime);
  transform: rotate(1.35deg);
}

.art-frame {
  position: relative;
  z-index: 1;
  overflow: hidden;
  padding: clamp(16px, 2.2vw, 23px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 28px;
  background:
    radial-gradient(120% 95% at 84% -8%, rgba(217, 243, 107, 0.18), transparent 44%),
    linear-gradient(150deg, #183b2b 0%, #0c2117 76%);
  box-shadow:
    0 38px 80px -30px rgba(12, 33, 23, 0.5),
    0 2px 3px rgba(12, 33, 23, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
  color: var(--paper);
}

.art-frame::before {
  content: "";
  position: absolute;
  right: -92px;
  bottom: -152px;
  width: 360px;
  height: 360px;
  border: 1px solid rgba(217, 243, 107, 0.18);
  border-radius: 50%;
  box-shadow:
    0 0 0 46px rgba(217, 243, 107, 0.025),
    0 0 0 92px rgba(217, 243, 107, 0.018);
  pointer-events: none;
}

.art-frame::after {
  content: "";
  position: absolute;
  top: -78px;
  right: -52px;
  width: 196px;
  height: 196px;
  border: 1px dashed rgba(217, 243, 107, 0.17);
  border-radius: 50%;
  pointer-events: none;
}

.art-chrome {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: clamp(14px, 2vw, 20px);
}

.art-brand {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--paper);
  font-size: 11px;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.art-brand svg {
  width: 19px;
  height: 19px;
}

.art-live {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: rgba(243, 240, 230, 0.58);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.art-live i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 0 3px rgba(217, 243, 107, 0.12);
}

.mock-sheet {
  position: relative;
  z-index: 2;
  overflow: hidden;
  padding: clamp(14px, 2vw, 21px);
  border: 1px solid rgba(16, 38, 27, 0.08);
  border-radius: 17px;
  background: var(--paper-high);
  color: var(--ink);
  box-shadow:
    0 24px 44px rgba(4, 15, 10, 0.24),
    0 1px 0 rgba(255, 255, 255, 0.84) inset;
}

.sheet-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.sheet-titles {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sheet-kicker {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.11em;
  line-height: 1.4;
  text-transform: uppercase;
}

.sheet-title {
  color: var(--ink);
  font-family: var(--serif);
  font-size: clamp(17px, 2.1vw, 22px);
  letter-spacing: -0.025em;
  line-height: 1.1;
}

.sheet-state {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  min-height: 22px;
  padding: 0 9px;
  border: 1px solid rgba(16, 38, 27, 0.14);
  border-radius: 999px;
  background: #f3eddc;
  color: #7b5d31;
  font-family: var(--mono);
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.sheet-cols {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: clamp(13px, 1.8vw, 18px);
  padding-bottom: 7px;
  border-bottom: 1px solid rgba(16, 38, 27, 0.11);
  color: #8b938b;
  font-family: var(--mono);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.txn {
  display: flex;
  align-items: center;
  gap: clamp(8px, 1.2vw, 11px);
  min-height: clamp(42px, 5vw, 49px);
  border-bottom: 1px solid rgba(16, 38, 27, 0.085);
}

.txn:last-child {
  border-bottom: 0;
}

.txn--flag {
  position: relative;
  margin-inline: calc(clamp(14px, 2vw, 21px) * -1);
  padding-inline: clamp(14px, 2vw, 21px);
  background: linear-gradient(90deg, rgba(246, 231, 210, 0.92), rgba(246, 231, 210, 0.38));
}

.txn--flag::before {
  content: "";
  position: absolute;
  top: 7px;
  bottom: 7px;
  left: 0;
  width: 2px;
  border-radius: 2px;
  background: var(--amber);
}

.txn-icon {
  display: grid;
  place-items: center;
  width: clamp(25px, 3.2vw, 31px);
  height: clamp(25px, 3.2vw, 31px);
  flex: 0 0 auto;
  border-radius: 8px;
}

.txn-icon svg {
  width: 14px;
  height: 14px;
}

.txn-icon--sage {
  background: var(--sage);
}

.txn-icon--sand {
  background: var(--amber-wash);
}

.txn-copy {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 1px;
}

.txn-name {
  overflow: hidden;
  color: var(--ink);
  font-size: clamp(9.5px, 1.15vw, 11.5px);
  font-weight: 630;
  letter-spacing: -0.01em;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.txn-category {
  color: var(--muted);
  font-size: clamp(8px, 0.95vw, 9.5px);
  line-height: 1.3;
}

.txn-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-height: 20px;
  padding: 0 7px;
  border-radius: 999px;
  font-family: var(--mono);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.025em;
  white-space: nowrap;
}

.txn-status svg {
  width: 9px;
  height: 9px;
  margin-right: 3px;
}

.txn-status--matched {
  background: var(--lime-wash);
  color: #36511d;
}

.txn-status--flag {
  background: var(--amber);
  color: var(--ink);
}

.sheet-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: clamp(12px, 1.8vw, 17px);
  padding-top: clamp(12px, 1.8vw, 16px);
  border-top: 1px solid rgba(16, 38, 27, 0.11);
}

.sheet-ready {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--ink-soft);
  font-size: clamp(8.5px, 1vw, 10px);
  font-weight: 560;
}

.sheet-ready svg {
  width: 12px;
  height: 12px;
  padding: 2px;
  border-radius: 50%;
  background: var(--lime);
  color: var(--ink);
}

.sheet-export {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 26px;
  padding: 0 10px;
  border-radius: 999px;
  background: var(--ink);
  color: var(--paper);
  font-size: clamp(8px, 0.95vw, 9.5px);
  font-weight: 600;
}

.sheet-export svg {
  width: 10px;
  height: 10px;
}

.art-sticker {
  position: absolute;
  z-index: 4;
  top: -4px;
  right: -1px;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  padding: 6px 13px 6px 7px;
  border: 1px solid rgba(16, 38, 27, 0.22);
  border-radius: 11px;
  background: var(--lime);
  box-shadow: 0 13px 28px -14px rgba(16, 38, 27, 0.48);
  color: var(--ink);
  font-size: clamp(9px, 1.15vw, 11px);
  font-weight: 650;
  letter-spacing: -0.015em;
  transform: rotate(3.2deg);
  transform-origin: 80% 50%;
  animation: sticker-settle 800ms 500ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.sticker-check {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  flex: 0 0 auto;
  border-radius: 7px;
  background: var(--ink);
  color: var(--lime);
}

.sticker-check svg {
  width: 14px;
  height: 14px;
}

@keyframes sticker-settle {
  from {
    transform: translateY(-7px) rotate(5deg);
  }
  to {
    transform: translateY(0) rotate(3.2deg);
  }
}

.features {
  position: relative;
  border-top: 1px solid var(--line);
  background: var(--paper);
}

.features-inner {
  padding-top: clamp(72px, 8.5vw, 118px);
  padding-bottom: clamp(76px, 9vw, 128px);
}

.features-grid {
  display: grid;
  grid-template-columns: minmax(230px, 0.82fr) minmax(0, 1.92fr);
  align-items: start;
  gap: clamp(48px, 7.5vw, 108px);
}

.features-intro {
  position: sticky;
  top: 120px;
  max-width: 385px;
}

.section-title {
  margin: 22px 0 0;
  color: var(--ink);
  font-family: var(--serif);
  font-size: clamp(2.65rem, 4.2vw, 4rem);
  font-weight: 400;
  letter-spacing: -0.05em;
  line-height: 0.98;
}

.section-title em {
  font-style: italic;
}

.features-intro > p:last-child {
  max-width: 34ch;
  margin: 24px 0 0;
  color: var(--ink-soft);
  font-size: 15.5px;
  line-height: 1.65;
  text-wrap: pretty;
}

.feature-list {
  border-top: 1px solid var(--line-strong);
}

.feature {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) minmax(160px, 202px);
  align-items: start;
  gap: clamp(15px, 2.5vw, 32px);
  padding: clamp(29px, 3.6vw, 42px) 0;
  border-bottom: 1px solid var(--line);
}

.feature-index {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  margin-top: 3px;
  border: 1px solid var(--line-strong);
  border-radius: 50%;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: -0.02em;
  transition: background 220ms ease, border-color 220ms ease, color 220ms ease;
}

.feature h3 {
  margin: 0;
  color: var(--ink);
  font-family: var(--serif);
  font-size: clamp(1.65rem, 2.2vw, 2rem);
  font-weight: 400;
  letter-spacing: -0.032em;
  line-height: 1.08;
}

.feature-copy p {
  max-width: 52ch;
  margin: 12px 0 0;
  color: var(--ink-soft);
  font-size: 14.5px;
  line-height: 1.65;
  text-wrap: pretty;
}

.feature-art {
  justify-self: end;
  align-self: center;
  width: 100%;
  max-width: 202px;
  border-radius: 16px;
  box-shadow: 0 12px 26px -20px rgba(16, 38, 27, 0.28);
  transition: transform 260ms cubic-bezier(0.2, 0.7, 0.2, 1), box-shadow 260ms ease;
}

.feature-art svg {
  width: 100%;
  height: auto;
  border-radius: 16px;
}

.feature:hover .feature-index {
  border-color: var(--ink);
  background: var(--lime);
  color: var(--ink);
}

.feature:hover .feature-art {
  box-shadow: 0 18px 32px -20px rgba(16, 38, 27, 0.38);
  transform: translateY(-3px);
}

.how {
  position: relative;
  overflow: hidden;
  border-top: 1px solid rgba(243, 240, 230, 0.09);
  background:
    radial-gradient(58% 76% at 92% 112%, rgba(217, 243, 107, 0.13), transparent 64%),
    linear-gradient(rgba(243, 240, 230, 0.032) 1px, transparent 1px),
    var(--ink);
  background-size: auto, 100% 58px, auto;
  color: var(--paper);
}

.how::before {
  content: "";
  position: absolute;
  top: -304px;
  right: -176px;
  width: 600px;
  height: 600px;
  border: 1px solid rgba(217, 243, 107, 0.11);
  border-radius: 50%;
  pointer-events: none;
}

.how::after {
  content: "";
  position: absolute;
  bottom: -452px;
  left: -238px;
  width: 656px;
  height: 656px;
  border: 1px solid rgba(217, 243, 107, 0.075);
  border-radius: 50%;
  pointer-events: none;
}

.how-inner {
  position: relative;
  z-index: 1;
  padding-top: clamp(78px, 9vw, 122px);
  padding-bottom: clamp(80px, 9vw, 124px);
}

.how-head {
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
  align-items: end;
  gap: clamp(32px, 7vw, 104px);
}

.how .section-title {
  max-width: 640px;
  margin-top: 24px;
  color: var(--paper);
  font-size: clamp(2.85rem, 4.9vw, 4.5rem);
  line-height: 0.96;
}

.how .section-title span {
  display: block;
}

.how-intro {
  max-width: 37ch;
  margin: 0 0 7px;
  justify-self: end;
  color: rgba(243, 240, 230, 0.63);
  font-size: 15.5px;
  line-height: 1.66;
  text-wrap: pretty;
}

.steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin: clamp(51px, 6vw, 78px) 0 0;
  padding: 0;
  border-top: 1px solid rgba(243, 240, 230, 0.17);
  list-style: none;
}

.step {
  position: relative;
  padding: clamp(25px, 2.8vw, 34px) clamp(22px, 3vw, 44px) 0 0;
}

.step + .step {
  padding-left: clamp(24px, 3.4vw, 48px);
  border-left: 1px solid rgba(243, 240, 230, 0.13);
}

.step:last-child {
  padding-right: 0;
}

.step-top {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-bottom: clamp(48px, 6vw, 78px);
  color: var(--lime);
}

.step-number {
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.1em;
}

.step-rule {
  width: 100%;
  height: 1px;
  background: linear-gradient(90deg, rgba(217, 243, 107, 0.42), rgba(217, 243, 107, 0.05));
}

.step-arrow,
.step-done {
  width: 15px;
  height: 15px;
  flex: 0 0 auto;
  color: var(--lime);
  opacity: 0.8;
}

.step h3 {
  max-width: 11ch;
  margin: 0 0 14px;
  color: var(--paper);
  font-family: var(--serif);
  font-size: clamp(1.6rem, 2.35vw, 2.05rem);
  font-weight: 400;
  letter-spacing: -0.035em;
  line-height: 1.04;
}

.step p {
  max-width: 31ch;
  margin: 0;
  color: rgba(243, 240, 230, 0.58);
  font-size: 14.5px;
  line-height: 1.66;
  text-wrap: pretty;
}

.step::after {
  content: "";
  position: absolute;
  top: -3px;
  left: 0;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 0 4px rgba(217, 243, 107, 0.1);
}

.step + .step::after {
  left: clamp(24px, 3.4vw, 48px);
}

.cta {
  position: relative;
  overflow: hidden;
  border-top: 1px solid rgba(16, 38, 27, 0.28);
  background:
    linear-gradient(90deg, rgba(16, 38, 27, 0.055) 1px, transparent 1px),
    var(--lime);
  background-size: 98px 100%;
  color: var(--ink);
}

.cta::before {
  content: "";
  position: absolute;
  right: -140px;
  bottom: -360px;
  width: 620px;
  height: 620px;
  border: 1px solid rgba(16, 38, 27, 0.16);
  border-radius: 50%;
  pointer-events: none;
}

.cta-inner {
  position: relative;
  z-index: 1;
  padding-top: clamp(74px, 8vw, 112px);
  padding-bottom: clamp(31px, 3.2vw, 42px);
}

.cta-main {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 214px;
  align-items: center;
  gap: clamp(40px, 7vw, 100px);
}

.cta .eyebrow {
  color: rgba(16, 38, 27, 0.66);
}

.cta .eyebrow-dot {
  background: var(--ink);
  box-shadow: 0 0 0 4px rgba(16, 38, 27, 0.13);
}

.cta-title {
  max-width: 1000px;
  margin: 24px 0 0;
  color: var(--ink);
  font-family: var(--serif);
  font-size: clamp(3.1rem, 6.3vw, 6.1rem);
  font-weight: 400;
  letter-spacing: -0.058em;
  line-height: 0.92;
}

.cta-title span {
  display: block;
}

.cta-title em {
  font-style: italic;
}

.cta-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px 24px;
  margin-top: clamp(32px, 4vw, 47px);
}

.cta .button {
  border-color: var(--ink);
  background: var(--ink);
  color: var(--paper);
}

.cta .button:hover {
  background: #1d3c2b;
  box-shadow: 0 10px 28px rgba(16, 38, 27, 0.2);
}

.cta .text-link {
  border-color: rgba(16, 38, 27, 0.35);
}

.cta .text-link:hover {
  border-color: var(--ink);
}

.cta-seal {
  position: relative;
  display: grid;
  place-items: center;
  width: 214px;
  height: 214px;
  justify-self: end;
  border-radius: 50%;
  background: var(--ink);
  color: var(--lime);
  transform: rotate(-6deg);
  box-shadow: 0 24px 42px -26px rgba(16, 38, 27, 0.5);
}

.cta-seal::before {
  content: "";
  position: absolute;
  inset: -13px;
  border: 1px dashed rgba(16, 38, 27, 0.4);
  border-radius: 50%;
  animation: seal-turn 40s linear infinite;
}

.cta-seal::after {
  content: "";
  position: absolute;
  inset: 13px;
  border: 1px solid rgba(217, 243, 107, 0.23);
  border-radius: 50%;
}

.cta-seal svg {
  width: 74px;
  height: 74px;
}

.seal-caption {
  position: absolute;
  bottom: 42px;
  left: 50%;
  color: rgba(243, 240, 230, 0.54);
  font-family: var(--mono);
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  transform: translateX(-50%);
  white-space: nowrap;
}

@keyframes seal-turn {
  to {
    transform: rotate(360deg);
  }
}

.cta-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-top: clamp(54px, 6vw, 82px);
  padding-top: 22px;
  border-top: 1px solid rgba(16, 38, 27, 0.26);
  color: rgba(16, 38, 27, 0.65);
  font-size: 11.5px;
}

.cta-foot .brand {
  gap: 8px;
  font-size: 15px;
}

.cta-foot .brand-mark {
  width: 24px;
  height: 24px;
}

.cta-foot p {
  margin: 0;
}

.cta-foot .copyright {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.03em;
}

