  .hero-title {
    font-size: clamp(3.5rem, 7vw, 5.8rem);
  }

  .feature {
    grid-template-columns: 34px minmax(0, 1fr) minmax(145px, 174px);
  }

  .feature-copy p {
    font-size: 14px;
  }
}

@media (max-width: 960px) {
