    gap: 48px;
    padding-top: clamp(48px, 8vw, 72px);
    padding-bottom: clamp(58px, 8vw, 80px);
  }

  .hero-copy {
    max-width: 720px;
  }

  .hero-title {
    font-size: clamp(4rem, 9.2vw, 6.3rem);
  }

