  .features-grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 50px;
  }

  .features-intro {
    position: static;
    max-width: 540px;
  }

  .features-intro > p:last-child {
    max-width: 46ch;
  }

  .feature-list {
    max-width: 800px;
  }

  .feature {
    grid-template-columns: 34px minmax(0, 1fr) minmax(170px, 202px);
  }

  .how-head {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }

  .how-intro {
    max-width: 48ch;
    justify-self: start;
    margin-top: 2px;
  }

  .cta-main {
    grid-template-columns: minmax(0, 1fr) 168px;
    gap: 36px;
  }

  .cta-seal {
    width: 168px;
    height: 168px;
  }

  .cta-seal svg {
