    gap: 10px 18px;
  }

  .hero-meta {
    margin-top: 24px;
    font-size: 9.5px;
  }

  .features-inner {
    padding-top: 66px;
    padding-bottom: 76px;
  }

  .features-intro > p:last-child {
    margin-top: 18px;
  }

  .feature {
    grid-template-columns: 32px minmax(0, 1fr);
    gap: 14px;
    padding: 29px 0;
  }

  .feature-index {
    width: 31px;
    height: 31px;
    margin-top: 2px;
    font-size: 8.5px;
  }

  .feature-copy p {
    font-size: 14.5px;
  }

  .feature-art {
    grid-column: 2;
    width: min(100%, 248px);
