    margin-top: 15px;
    justify-self: start;
  }

  .how-inner {
    padding-top: 70px;
    padding-bottom: 72px;
  }

  .how .section-title {
    margin-top: 20px;
    font-size: clamp(2.8rem, 9.6vw, 3.9rem);
  }

  .steps {
    grid-template-columns: minmax(0, 1fr);
    margin-top: 40px;
    border-top: 0;
  }

  .step,
  .step + .step {
    padding: 25px 0 27px;
    border-left: 0;
    border-top: 1px solid rgba(243, 240, 230, 0.15);
  }

  .step-top {
    margin-bottom: 24px;
  }

  .step h3 {
    max-width: none;
    margin-bottom: 9px;
  }

  .step p {
    max-width: 50ch;
  }

  .step::after,
  .step + .step::after {
    top: -3px;
    left: 0;
  }

  .cta-main {
    grid-template-columns: minmax(0, 1fr);
    gap: 0;
  }

  .cta-seal {
    display: none;
  }

  .cta-title {
    font-size: clamp(2.9rem, 11.6vw, 4.7rem);
  }

  .cta-actions {
    margin-top: 31px;
  }

  .cta-foot {
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 9px 20px;
    margin-top: 48px;
  }

  .cta-foot .tagline {
    display: none;
  }
}

