  .txn-status svg {
    display: none;
  }

  .sheet-foot {
    margin-top: 10px;
    padding-top: 10px;
  }

  .sheet-ready {
    font-size: 7.5px;
  }

  .sheet-export {
    min-height: 23px;
    padding-inline: 8px;
    font-size: 7.5px;
  }

  .art-sticker {
    top: -7px;
    right: -2px;
    min-height: 33px;
    padding: 4px 9px 4px 5px;
    border-radius: 9px;
    font-size: 8.5px;
    gap: 6px;
