    border-radius: 6px;
  }

  .sticker-check svg {
    width: 12px;
    height: 12px;
  }

  .section-title {
    font-size: clamp(2.35rem, 10.6vw, 3rem);
  }

  .features-inner {
    padding-top: 55px;
    padding-bottom: 64px;
