  }

  .how-inner {
    padding-top: 59px;
    padding-bottom: 62px;
  }

  .how .section-title {
    font-size: clamp(2.5rem, 10.8vw, 3.2rem);
  }

  .how-intro {
    font-size: 14.5px;
  }

  .cta-inner {
    padding-top: 58px;
    padding-bottom: 28px;
  }

  .cta-title {
    font-size: clamp(2.55rem, 11.9vw, 3.3rem);
    line-height: 0.94;
  }

