    margin-top: 27px;
  }

  .cta-foot {
    margin-top: 40px;
    padding-top: 18px;
    font-size: 10.5px;
  }

  .cta-foot .brand {
    font-size: 14px;
  }

  .cta-foot .copyright {
    font-size: 8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
